const prefixMap = { IT: 'IT', HR: 'HR', Finance: 'FIN', Admin: 'ADM', Other: 'GEN' };
const ctx = $('Validate Ticket Fields').first().json;
const prefix = prefixMap[ctx.category] || 'GEN';
const rows = $input.all().map(i => i.json);
let maxNum = 1000;
for (const r of rows) {
  const m = new RegExp('^' + prefix + '-(\\d+)$').exec(r.ticket_id || '');
  if (m) { const n = parseInt(m[1], 10); if (n > maxNum) maxNum = n; }
}
const ticketId = prefix + '-' + (maxNum + 1);
return [{ json: { ...ctx, ticket_id: ticketId, created_at: new Date().toISOString() } }];

const d = $json;
const validCategories = ['IT', 'HR', 'Finance', 'Admin', 'Other'];
const validPriorities = ['low', 'medium', 'high', 'critical'];
let category = d.category && validCategories.includes(d.category) ? d.category : 'Other';
let priority = d.priority && validPriorities.includes(d.priority) ? d.priority : 'medium';
const description = d.description || $('Normalize Telegram Input').item.json.message_text;
const valid = !!description && description.trim().length > 3;
return { ...d, category, priority, description, valid };

