parameters.jsCode:
const rows = $input.all().map(i => i.json);
let maxNum = 1000;
for (const r of rows) {
  const m = /^LV-(\d+)$/.exec(r.request_id || '');
  if (m) { const n = parseInt(m[1], 10); if (n > maxNum) maxNum = n; }
}
const nextId = 'LV-' + (maxNum + 1);
const ctx = $('Check Sufficient Balance').first().json;
return [{ json: { ...ctx, request_id: nextId, created_at: new Date().toISOString() } }];

const bal = $json;
const req = $('Validate Leave Request').item.json;
const field = req.leave_type;
const remaining = Number(bal[field] || 0) - Number(bal['used_' + field] || 0);
return { ...req, remaining, sufficient: remaining >= req.days };

const d = $json;
const validTypes = ['annual', 'casual', 'sick'];
const errors = [];
const leaveType = (d.leave_type || '').toLowerCase();
const from = new Date(d.from_date);
const to = new Date(d.to_date);
const today = new Date(); today.setHours(0,0,0,0);
if (isNaN(from.getTime()) || isNaN(to.getTime())) errors.push('Invalid date format. Please use YYYY-MM-DD.');
if (!validTypes.includes(leaveType)) errors.push('Invalid leave type. Use annual, casual, or sick.');
let days = 0;
if (errors.length === 0) {
  if (from > to) errors.push('From date must be on or before the To date.');
  if (from < today) errors.push('Leave cannot be requested for a past date.');
}
if (errors.length === 0) {
  days = Math.round((to - from) / 86400000) + 1;
}
return { ...d, leave_type: leaveType, days, valid: errors.length === 0, errors };

const d = $json;
const missing = [];
if (!d.leave_type) missing.push('leave type (annual/casual/sick)');
if (!d.from_date) missing.push('from date');
if (!d.to_date) missing.push('to date');
if (!d.reason) missing.push('reason');
return { ...d, missing, hasMissing: missing.length > 0 };

const row = $json;
const annual = Number(row.annual || 0) - Number(row.used_annual || 0);
const casual = Number(row.casual || 0) - Number(row.used_casual || 0);
const sick = Number(row.sick || 0) - Number(row.used_sick || 0);
return { annual_remaining: annual, casual_remaining: casual, sick_remaining: sick };

