const messageText = ($('Normalize Telegram Input').first().json.message_text || '').toLowerCase();
const words = messageText.split(/\s+/).filter(w => w.length > 2);
let best = null, bestScore = 0;
for (const item of $input.all()) {
  const row = item.json;
  const kw = (row.keywords || '').toLowerCase();
  const q = (row.question || '').toLowerCase();
  let score = 0;
  for (const w of words) {
    if (kw.includes(w)) score += 2;
    if (q.includes(w)) score += 1;
  }
  if (score > bestScore) { bestScore = score; best = row; }
}
if (best && bestScore >= 2) {
  return [{ json: { found: true, policy_answer: best.answer, policy_question: best.question, category: best.category } }];
}
return [{ json: { found: false } }];

const allowed = ['hr_policy','leave_balance','leave_request','leave_status','ticket_create','ticket_status','general_hr','general_it','unknown'];
let raw = '';
try {
  raw = $json.choices[0].message.content;
} catch (e) {
  return { valid: false, error: 'LLM call failed or returned no content' };
}
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  return { valid: false, error: 'LLM returned malformed JSON', raw };
}
if (!parsed.intent || !allowed.includes(parsed.intent)) {
  return { valid: false, error: 'LLM returned an unrecognized intent', raw };
}
return { valid: true, ...parsed };

