const msg = $json.message || {};
const from = msg.from || {};
const chat = msg.chat || {};
return {
  telegram_user_id: from.id ? String(from.id) : '',
  chat_id: chat.id ? String(chat.id) : '',
  username: from.username || from.first_name || 'Unknown',
  message_text: msg.text ? String(msg.text).trim() : '',
  message_type: msg.text ? 'text' : (msg.voice ? 'voice' : (msg.photo ? 'photo' : 'unsupported')),
  timestamp: msg.date ? new Date(msg.date * 1000).toISOString() : new Date().toISOString()
};
